def gen(rng):
    def build(n, parent, relabel=True):
        labels = list(range(n))
        if relabel:
            rest = labels[1:]
            rng.shuffle(rest)
            labels = [0] + rest
        edges = []
        for i in range(1, n):
            a, b = labels[parent[i]], labels[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        rng.shuffle(edges)
        return str(n) + ("\n" if edges else "") + "\n".join(f"{a} {b}" for a, b in edges)

    def rand_parent(n, window=None):
        par = [0] * n
        for i in range(1, n):
            lo = 0 if window is None else max(0, i - window)
            par[i] = rng.randint(lo, i - 1)
        return par

    def deep_parent(n, depth):
        par = [0] * n
        for i in range(1, n):
            if i < depth:
                par[i] = i - 1
            else:
                par[i] = rng.randint(0, depth - 2)
        return par

    def two_arms(n, arm):
        # root in the middle of a long path, plus a few extra nodes hanging off the arms
        par = [0] * n
        for i in range(1, n):
            if i <= arm:
                par[i] = i - 1 if i > 1 else 0
            elif i <= 2 * arm:
                par[i] = i - 1 if i > arm + 1 else 0
            else:
                par[i] = rng.randint(0, 2 * arm - 1)
        return par

    tests = [
        "1",
        "2\n0 1",
        "3\n0 1\n2 0",
        "6\n0 1\n1 2\n1 3\n2 4\n3 5",
        "5\n0 1\n0 2\n0 3\n4 0",
        "4\n0 1\n1 2\n2 3",
        "4\n3 2\n2 1\n1 0",
        "7\n0 1\n0 2\n1 3\n1 4\n2 5\n2 6",
    ]
    for n in (4, 5, 6, 8, 10, 12, 15, 20, 30):
        for _ in range(3):
            tests.append(build(n, rand_parent(n, rng.choice([None, 2, 1]))))
    tests.append(build(2000, rand_parent(2000, 3)))
    tests.append(build(3000, rand_parent(3000)))
    tests.append(build(1000, two_arms(1000, 300)))
    # max-size cases
    n = 100000
    tests.append(build(n, rand_parent(n)))
    tests.append(build(n, [0] * n))
    tests.append(build(n, deep_parent(n, 5000)))
    tests.append(build(n, two_arms(n, 2400)))
    return tests
